PRAGMA foreign_keys = ON;

CREATE TABLE shops (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    platform TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('own', 'competitor')),
    score_enabled INTEGER NOT NULL DEFAULT 0,
    reception_enabled INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(name, platform, kind)
  );

CREATE TABLE metrics (
    id INTEGER PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    unit TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(name, category, unit)
  );

CREATE TABLE daily_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    report_date TEXT NOT NULL,
    shop_id INTEGER NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
    metric_id INTEGER NOT NULL REFERENCES metrics(id) ON DELETE CASCADE,
    numeric_value REAL,
    text_value TEXT,
    target_operator TEXT,
    target_value REAL,
    source_sheet TEXT NOT NULL DEFAULT '网页录入',
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(report_date, shop_id, metric_id)
  );

CREATE INDEX daily_records_date_idx ON daily_records(report_date);

CREATE INDEX daily_records_shop_date_idx ON daily_records(shop_id, report_date);

CREATE INDEX daily_records_metric_date_idx ON daily_records(metric_id, report_date);








































































































































